DROP TABLE IF EXISTS `xwq_ai_record`;
CREATE TABLE `xwq_ai_record`  (
  `record_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '唯一标识一次识别行为',
  `record_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '识别记录编号',
  `record_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '识别类型：病虫害、虫情、物候期',
  `record_mode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '识别方式：手动上传、自动定时',
  `model_id` bigint(0) NOT NULL COMMENT '本次识别使用的模型 ID',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '本次识别使用的模型名称快照',
