  `device_id` bigint(0) DEFAULT NULL COMMENT '来源设备 ID',
  `park_id` bigint(0) DEFAULT NULL COMMENT '所属园区',
  `plot_id` bigint(0) DEFAULT NULL COMMENT '所属地块',
  `record_status` tinyint(0) NOT NULL DEFAULT 0 COMMENT '识别状态：0 待识别，1 识别中，2 成功，3 失败',
  `record_a` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段1',
