  INDEX `idx_record_image_id`(`image_id`) USING BTREE,
  INDEX `idx_record_crop_type`(`crop_type`) USING BTREE,
  INDEX `idx_record_device_id`(`device_id`) USING BTREE,
  INDEX `idx_record_park_id`(`park_id`) USING BTREE,
  INDEX `idx_record_plot_id`(`plot_id`) USING BTREE,
  INDEX `idx_record_status`(`record_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9200 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '识别记录表' ROW_FORMAT = Dynamic;

